import {blankClientInvoice,clientInvoiceTotals} from '../../lib/client-invoices.ts';
export const uuid=n=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`;
export function invoiceDocument(){return {...blankClientInvoice('2026-01-01'),issuer:{name:'Synthetic Management Ltd',address:'Synthetic issuer address',email:'issuer@example.invalid',companyNumber:'SYNTHETIC',vatRegistered:false,vatNumber:''},client:{name:'Synthetic Client Ltd',address:'Synthetic client address',email:'client@example.invalid'},periodEnd:'2026-01-31',dueDate:'2026-01-31',paymentInstructions:'Reviewed synthetic payment instructions',lines:[{id:uuid(1),description:'Management fee',quantityMilli:1000,unitPricePence:10000,vatRateBps:0}]};}
export function invoiceRecord(patch={}){const document=patch.document??invoiceDocument(),totals=clientInvoiceTotals(document);return {id:uuid(1),block_id:1,block_snapshot:{name:'Synthetic Court',address:'Synthetic address'},status:'Draft',invoice_number:null,revision:1,document,net_pence:totals.netPence,vat_pence:totals.vatPence,total_pence:totals.totalPence,created_by:'owner@example.invalid',created_at:'2026-01-01T12:00:00Z',updated_by:'owner@example.invalid',updated_at:'2026-01-01T12:00:00Z',reviewed_by:null,reviewed_at:null,issued_by:null,issued_at:null,voided_by:null,voided_at:null,void_reason:null,...patch};}
